mapper.select:
SELECT m.* FROM `t_escalation_material` m WHERE m.`del_flag` = 0 AND m.`project_id` IN
#{pid}
ORDER BY m.`project_id`, m.`material_type`, m.`version`, m.`id`

SELECT COUNT(1) AS fileCount, COALESCE(SUM(m.`file_size`), 0) AS totalSize
FROM `t_escalation_material` m
WHERE m.`del_flag` = 0 AND m.`project_id` = #{projectId}
